  "claim": {
    "component_id": "C005.component",
    "value": "Meeting minutes cannot be assumed to satisfy the approval rule merely because they are available as approval-related records.",
    "scope": "Potential use of meeting minutes; neither their sufficiency nor their insufficiency is established categorically.",
    "provenance": {
      "refs": [
        {
          "source_id": "P004",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly withholds automatic rule satisfaction from meeting minutes without categorically excluding them."
    }
  },
  "signal_basis": {
    "component_id": "C005.signal_basis",
    "value": "Gather relevant meeting minutes, cross-check order identity, scope, people and dates, and seek independent agreement on approver authority and documented approval before placement against the applicable approval requirements.",
    "scope": "Proposed checks for individual flagged orders, evaluated assuming execution and the described signal; the mapping reports no completed observations.",
